source='''def extract_layout(grid):
    h, w = len(grid), len(grid[0])
    horizontal = [r for r, row in enumerate(grid) if len(set(row)) == 1 and row[0] != 0]
    vertical = [c for c in range(w) if len({grid[r][c] for r in range(h)}) == 1 and grid[0][c] != 0]
    row_starts = [0] + [r + 1 for r in horizontal]
    row_ends = horizontal + [h]
    col_starts = [0] + [c + 1 for c in vertical]
    col_ends = vertical + [w]
    cells = [
        [[row[c0:c1] for row in grid[r0:r1]] for c0, c1 in zip(col_starts, col_ends)]
        for r0, r1 in zip(row_starts, row_ends)
    ]
    return cells, list(zip(row_starts, row_ends)), list(zip(col_starts, col_ends))


def reflect(pattern, vertical=False, horizontal=False):
    result = [row[::-1] if horizontal else row[:] for row in pattern]
    if vertical:
        result.reverse()
    return result


def panel_data(panel):
    colors = {value for row in panel for value in row if value != 0}
    if len(colors) != 1:
        return None, None
    return next(iter(colors)), panel


def transform(grid):
    out = [row[:] for row in grid]
    cells, row_ranges, col_ranges = extract_layout(grid)
    row_count, col_count = len(cells), len(cells[0])
    additions = {}

    for r in range(row_count - 1):
        for c in range(col_count - 1):
            panels = [cells[r + dr][c + dc] for dr, dc in ((0, 0), (0, 1), (1, 0), (1, 1))]
            info = [panel_data(panel) for panel in panels]
            present = [(k, info[k][0], info[k][1]) for k in range(4) if info[k][0] is not None]
            if len(present) != 3 or len({color for _, color, _ in present}) != 1:
                continue

            canonical = []
            for k, _, pattern in present:
                dr, dc = divmod(k, 2)
                canonical.append(reflect(pattern, vertical=bool(dr), horizontal=bool(dc)))
            if not all(pattern == canonical[0] for pattern in canonical[1:]):
                continue

            missing = next(k for k in range(4) if info[k][0] is None)
            dr, dc = divmod(missing, 2)
            additions[(r + dr, c + dc)] = (
                present[0][1],
                reflect(canonical[0], vertical=bool(dr), horizontal=bool(dc)),
            )

    for (r, c), (color, pattern) in additions.items():
        r0, r1 = row_ranges[r]
        c0, c1 = col_ranges[c]
        for i in range(min(r1 - r0, len(pattern))):
            for j in range(min(c1 - c0, len(pattern[i]))):
                if pattern[i][j] != 0:
                    out[r0 + i][c0 + j] = color
    return out
'''
